package org.eclipse.rdf4j.sail.lmdb.evaluation;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;

/**
 * The shared physical cost of running a native plan, as feature counts. Every strategy that executes a plan tree prices
 * the plan's statement access here, through {@link LmdbNativeAccessFacts}, and adds its own per-row execution feature:
 * an interpreted nested loop pays {@link Feature#INTERPRETED_ROW} per intermediate row, a compiled kernel
 * {@link Feature#GENERATED_ROW}, a batch or factorized operator {@link Feature#BATCH_ROW}. Because the access part is
 * identical for all of them, two strategies over the same plan differ exactly by what they do differently.
 */
final class LmdbNativeCostVectors {

	private LmdbNativeCostVectors() {
	}

	/** A vector whose ceiling is unknown: it takes part in no comparison. */
	static LmdbNativeCostVector unbounded() {
		return LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, 0D, LmdbNativeCostQuote.UNBOUNDED_COUNT);
	}

	/** The store's statement count from the row's source profile, or NaN when no profile is available. */
	static double statementCount(RowState row) {
		NativeLmdbQuerySource.IndexAccessProfile profile = row == null || row.source == null ? null
				: row.source.indexAccessProfile();
		return profile != null && profile.entries() >= 0L ? profile.entries() : Double.NaN;
	}

	/**
	 * The ceiling of the fallback an unpriceable plan degrades to: a sweep of the store's smallest index with one
	 * {@code rowFeature} per statement. Unbounded when the source cannot say how many statements it holds.
	 */
	static LmdbNativeCostVector sweep(RowState row, Feature rowFeature) {
		double entries = statementCount(row);
		if (Double.isNaN(entries)) {
			return unbounded();
		}
		LmdbNativeCostVector scan = LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, entries / 2D, entries);
		return rowFeature == null || rowFeature == Feature.SCANNED_ROW ? scan
				: scan.plus(perRow(rowFeature, Double.NaN, row));
	}

	/**
	 * {@code count} occurrences of {@code feature}; an unknown count is bounded by the store's statement count (no
	 * single plan emits more rows than a sweep of the store) when the row's source can say it, else unbounded.
	 */
	static LmdbNativeCostVector perRow(Feature feature, double count, RowState row) {
		if (!Double.isNaN(count)) {
			return perRow(feature, count);
		}
		double entries = statementCount(row);
		return Double.isNaN(entries) ? unbounded() : LmdbNativeCostVector.bounds(feature, 0D, entries / 2D, entries);
	}

	/** The same ceiling as a work interval, for proposals that still quote intervals. */
	static LmdbNativeWork sweepWork(RowState row) {
		double entries = statementCount(row);
		return Double.isNaN(entries) ? LmdbNativeWork.UNKNOWN : LmdbNativeWork.between(0D, 2D * entries);
	}

	/** Rows a plan emits under a bound mask for planning purposes, or NaN when unknown. */
	static double rows(SlotPlan plan, RowState row, long boundMask) {
		if (plan instanceof PatternPlan pattern) {
			double rows = pattern.estimateForBoundMask(boundMask, row == null ? null : row.source);
			return Double.isFinite(rows) && rows >= 0D ? rows : Double.NaN;
		}
		return LmdbNativeWork.rowsOut(plan, row, boundMask);
	}

	/** Access features of one statement pattern under a bound mask. */
	static LmdbNativeCostVector pattern(PatternPlan pattern, RowState row, long boundMask) {
		LmdbNativeAccessFacts facts = LmdbNativeAccessFacts.forPattern(pattern, row == null ? null : row.source);
		if (facts == null) {
			LmdbNativeWork work = pattern.estimateWork(row, boundMask);
			return work.known()
					? LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, work.low(), (work.low() + work.high()) / 2D,
							work.high())
					: sweep(row, null);
		}
		LmdbNativeAccessFacts.Quote quote = facts.quote(pattern.physicalMask(boundMask));
		int scans = pattern.contexts.isFixed() && (quote.physicalMask() & LmdbNativeAccessFacts.CONTEXT) == 0
				? pattern.contexts.ids.length
				: 1;
		return quote.vector(pattern.accessProfile.sources(), scans);
	}

	/**
	 * Features of evaluating {@code plan} as a left-deep pipeline where every intermediate row costs
	 * {@code rowFeature}. Probes of a right side are repeated once per left row.
	 */
	static LmdbNativeCostVector plan(SlotPlan plan, RowState row, long boundMask, Feature rowFeature) {
		if (plan instanceof EmptyPlan || plan instanceof SingletonPlan) {
			return LmdbNativeCostVector.zero();
		}
		if (plan instanceof PatternPlan pattern) {
			double rows = rows(pattern, row, boundMask);
			return pattern(pattern, row, boundMask).plus(perRow(rowFeature, rows, row));
		}
		if (plan instanceof ValuesPlan values) {
			return perRow(rowFeature, values.rows.length);
		}
		if (plan instanceof UnionPlan union) {
			return plan(union.left, row, boundMask, rowFeature).plus(plan(union.right, row, boundMask, rowFeature));
		}
		if (plan instanceof FilterPlan filter) {
			return plan(filter.arg, row, boundMask, rowFeature)
					.plus(perRow(Feature.INTERPRETED_ROW, rows(filter.arg, row, boundMask), row));
		}
		if (plan instanceof ExtensionPlan extension) {
			double rows = rows(extension.arg, row, boundMask);
			return plan(extension.arg, row, boundMask, rowFeature)
					.plus(perRow(Feature.INTERPRETED_ROW, multiply(rows, extension.copies.length), row));
		}
		if (plan instanceof RowDistinctPlan distinct) {
			return plan(distinct.arg, row, boundMask, rowFeature)
					.plus(perRow(Feature.MEMBERSHIP_TEST, rows(distinct.arg, row, boundMask), row));
		}
		if (plan instanceof JoinPlan join) {
			return probe(join.left, join.right, row, boundMask, rowFeature);
		}
		if (plan instanceof LeftJoinPlan leftJoin) {
			return probe(leftJoin.left, leftJoin.right, row, boundMask, rowFeature);
		}
		if (plan instanceof LateralPlan lateral) {
			return probe(lateral.left, lateral.right, row, boundMask, rowFeature);
		}
		if (plan instanceof MinusPlan minus) {
			return probe(minus.left, minus.right, row, boundMask, rowFeature);
		}
		if (plan instanceof MultiJoinPlan multiJoin) {
			MultiJoinPlan.OrderedPlan ordered = multiJoin.derivedPlan(boundMask);
			return chain(ordered.order, ordered.order.length, row, boundMask, rowFeature);
		}
		if (plan instanceof NativeAliasJoinPlan alias) {
			return plan(alias.original, row, boundMask, rowFeature);
		}
		if (plan instanceof NativeAliasJoinMemoPlan memo) {
			return plan(memo.original, row, boundMask, rowFeature);
		}
		LmdbNativeWork work = plan.estimateWork(row, boundMask);
		return work.known()
				? LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, work.low(), (work.low() + work.high()) / 2D,
						work.high())
				: sweep(row, rowFeature);
	}

	/** Left side once, right side once per left row. */
	static LmdbNativeCostVector probe(SlotPlan left, SlotPlan right, RowState row, long boundMask,
			Feature rowFeature) {
		LmdbNativeCostVector leftVector = plan(left, row, boundMask, rowFeature);
		double leftRows = rows(left, row, boundMask);
		if (Double.isNaN(leftRows)) {
			return leftVector.plus(sweep(row, rowFeature));
		}
		LmdbNativeCostVector rightVector = plan(right, row, boundMask | left.producedMask(), rowFeature);
		return leftVector.plus(rightVector.scale(leftRows));
	}

	/** A nested-loop chain: each child is probed once per row of the prefix before it. */
	static LmdbNativeCostVector chain(SlotPlan[] children, int length, RowState row, long boundMask,
			Feature rowFeature) {
		LmdbNativeCostVector total = LmdbNativeCostVector.zero();
		double prefixRows = 1D;
		long mask = boundMask;
		for (int i = 0; i < length; i++) {
			LmdbNativeCostVector child = plan(children[i], row, mask, rowFeature);
			total = total.plus(child.scale(prefixRows));
			double childRows = rows(children[i], row, mask);
			if (Double.isNaN(childRows)) {
				// this child is already priced (as a sweep when unpriceable); every later child loses its
				// multiplier and degrades to one sweep per prefix row
				for (int j = i + 1; j < length; j++) {
					total = total.plus(sweep(row, rowFeature).scale(prefixRows));
				}
				return total;
			}
			prefixRows *= childRows;
			mask |= children[i].producedMask();
		}
		return total;
	}

	/**
	 * A factorized evaluation: the first {@code prefixLength} children form a nested-loop chain; the remaining children
	 * are branches probed side by side once per prefix row, summed rather than multiplied.
	 */
	/** What a factorized branch does with its rows: enumerates them, counts them, or checks that one exists. */
	enum BranchRole {
		ENUM,
		COUNT,
		EXISTS
	}

	/**
	 * A factorized row join as its executor runs it ({@code LmdbNativeFactorizedRows}): the prefix is a nested-loop
	 * chain with a batch row per intermediate row; each branch result is memoised per probe key, so a branch is
	 * accessed once per DISTINCT key the prefix carries into it (expected) and at worst once per prefix row (high, when
	 * the memo refuses); a COUNT branch counts its rows without decoding them, an EXISTS branch reads one record per
	 * key, an ENUM branch decodes and packs its rows once per key; the memo is consulted once per prefix row; and one
	 * batch row is emitted per logical output row (counts become the row's multiplicity). A keys-only root walks
	 * {@code depth0Keys} keys without decoding a run.
	 */
	static LmdbNativeCostVector factorizedRows(SlotPlan[] order, int prefixLength, BranchRole[] roles,
			double depth0Keys, RowState row, long boundMask) {
		if (prefixLength < 0 || prefixLength > order.length || roles.length != order.length - prefixLength) {
			return unbounded();
		}
		LmdbNativeFanOutFacts facts = LmdbNativeFanOutFacts.forFactorized(order, order.length, prefixLength, row,
				boundMask, depth0Keys);
		if (!facts.priceable()) {
			// an unpriceable child keeps the sweep ceiling of the chain form
			return factorized(order, prefixLength, row, boundMask, Feature.BATCH_ROW);
		}
		LmdbNativeCostVector total = LmdbNativeCostVector.zero();
		for (int i = 0; i < prefixLength; i++) {
			LmdbNativeFanOutFacts.Depth depth = facts.depth(i);
			LmdbNativeCostVector access;
			if (i == 0 && Double.isFinite(depth0Keys) && depth0Keys >= 0D && order[0] instanceof PatternPlan) {
				double keys = Math.min(depth0Keys, depth.rowsPerKey());
				access = LmdbNativeCostVector.point(Feature.INDEX_SEEK, 1D)
						.plus(perRow(Feature.SCANNED_ROW, keys))
						.plus(perRow(Feature.BATCH_ROW, keys));
			} else {
				access = plan(order[i], row, depth.maskBefore(), Feature.BATCH_ROW);
			}
			total = total.plus(access.scale(depth.prefixRows()));
		}
		double prefixRows = facts.prefixRowsAfterPrefix();
		double emitted = prefixRows;
		for (int b = prefixLength; b < order.length; b++) {
			LmdbNativeFanOutFacts.Depth depth = facts.depth(b);
			BranchRole role = roles[b - prefixLength];
			double keys = depth.distinctKeys();
			double hitting = depth.hittingKeys();
			LmdbNativeCostVector probe = order[b] instanceof PatternPlan pattern
					? pattern(pattern, row, depth.maskBefore())
					: plan(order[b], row, depth.maskBefore(), Feature.SCANNED_ROW);
			// seeks once per distinct key, rows once per key that has any; at worst once per prefix row
			total = total.plus(scaled(probe, Feature.INDEX_SEEK, keys, prefixRows));
			if (role == BranchRole.EXISTS) {
				total = total.plus(LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D,
						Math.min(1D, probe.expected(Feature.SCANNED_ROW)) * hitting,
						Math.max(hitting, Math.min(1D, probe.high(Feature.SCANNED_ROW)) * prefixRows)));
			} else {
				total = total.plus(scaled(probe, Feature.SCANNED_ROW, hitting, prefixRows));
				if (role == BranchRole.ENUM) {
					total = total.plus(scaled(probe, Feature.DECODED_ROW, hitting, prefixRows));
					double rowsPerKey = depth.rowsPerKey();
					total = total.plus(LmdbNativeCostVector.bounds(Feature.BATCH_ROW, 0D, hitting * rowsPerKey,
							Math.max(hitting, prefixRows) * rowsPerKey));
					emitted *= rowsPerKey;
				}
			}
			total = total.plus(perRow(Feature.HASH_PROBE, prefixRows));
		}
		return total.plus(perRow(Feature.BATCH_ROW, emitted));
	}

	/** One feature of {@code vector} scaled by {@code expectedScale} (low and expected) and {@code highScale}. */
	private static LmdbNativeCostVector scaled(LmdbNativeCostVector vector, Feature feature, double expectedScale,
			double highScale) {
		double low = vector.low(feature) * expectedScale;
		double expected = Math.max(low, vector.expected(feature) * expectedScale);
		double high = Math.max(expected, vector.high(feature) * Math.max(expectedScale, highScale));
		return high > 0D ? LmdbNativeCostVector.bounds(feature, low, expected, high) : LmdbNativeCostVector.zero();
	}

	static LmdbNativeCostVector factorized(SlotPlan[] order, int prefixLength, RowState row, long boundMask,
			Feature rowFeature) {
		if (prefixLength < 0 || prefixLength > order.length) {
			return unbounded();
		}
		LmdbNativeCostVector total = LmdbNativeCostVector.zero();
		double prefixRows = 1D;
		long mask = boundMask;
		for (int i = 0; i < prefixLength; i++) {
			total = total.plus(plan(order[i], row, mask, rowFeature).scale(prefixRows));
			double childRows = rows(order[i], row, mask);
			if (Double.isNaN(childRows)) {
				for (int j = i + 1; j < order.length; j++) {
					total = total.plus(sweep(row, rowFeature).scale(prefixRows));
				}
				return total;
			}
			prefixRows *= childRows;
			mask |= order[i].producedMask();
		}
		LmdbNativeCostVector branches = LmdbNativeCostVector.zero();
		for (int i = prefixLength; i < order.length; i++) {
			branches = branches.plus(plan(order[i], row, mask, rowFeature));
		}
		return total.plus(branches.scale(prefixRows));
	}

	/**
	 * A set-at-a-time evaluation of a join (leapfrog triejoin, packed factor tree): every pattern's relation is walked
	 * once, not once per prefix row, and each visited relation row plus each output row costs {@code rowFeature}.
	 * Measured on the cycle queries (2026-11-02): the nested-loop chain price overstated {@code wcoj} twelve-fold and
	 * the per-root-row expansion overstated the packed f-tree thirty-fold.
	 */
	static LmdbNativeCostVector setAtATime(SlotPlan plan, RowState row, long boundMask, Feature rowFeature) {
		if (!(plan instanceof MultiJoinPlan multiJoin)) {
			return plan(plan, row, boundMask, rowFeature);
		}
		LmdbNativeCostVector total = LmdbNativeCostVector.zero();
		double visited = 0D;
		long produced = 0L;
		for (SlotPlan child : multiJoin.children) {
			produced |= child.producedMask();
		}
		for (SlotPlan child : multiJoin.children) {
			// each relation is read with the entry bindings only; later patterns are intersected, not probed
			total = total.plus(plan(child, row, boundMask, rowFeature));
			double rows = rows(child, row, boundMask);
			if (Double.isNaN(rows)) {
				return total.plus(sweep(row, rowFeature));
			}
			visited += rows;
			long others = 0L;
			for (SlotPlan other : multiJoin.children) {
				others |= other == child ? 0L : other.producedMask();
			}
			total = total.plus(intersectionSeekPenalty(child, row, boundMask, others, rows));
		}
		double output = LmdbNativeWork.rowsOut(multiJoin, row, boundMask);
		return total.plus(perRow(rowFeature, Double.isNaN(output) ? visited : output));
	}

	/**
	 * A set-at-a-time join seeks each relation by the join variable it intersects on. When no index of the store leads
	 * with that variable (for example a predicate-bound pattern intersected on its object with only {@code spoc}
	 * configured), each seek is a walk of the pattern's whole range instead. Measured 2026-11-02 on {@code spoc}-only
	 * stores: the leapfrog join was 17 to 78 times slower than a probe chain while its quote saw nothing.
	 */
	private static LmdbNativeCostVector intersectionSeekPenalty(SlotPlan child, RowState row, long boundMask,
			long producedByOthers, double rows) {
		if (!(child instanceof PatternPlan pattern) || pattern.accessProfile == null || !(rows > 0D)) {
			return LmdbNativeCostVector.zero();
		}
		LmdbNativeAccessFacts facts = LmdbNativeAccessFacts.forPattern(pattern, row == null ? null : row.source);
		if (facts == null) {
			return LmdbNativeCostVector.zero();
		}
		LmdbNativeCostVector penalty = LmdbNativeCostVector.zero();
		for (Term term : new Term[] { pattern.s, pattern.o }) {
			if (!term.hasSlot() || (boundMask & (1L << term.slot)) != 0L) {
				continue;
			}
			// only a slot another pattern also produces is a join variable this relation is intersected on
			if ((producedByOthers & (1L << term.slot)) == 0L) {
				continue;
			}
			LmdbNativeAccessFacts.Quote keyed = facts.quote(pattern.physicalMask(boundMask | (1L << term.slot)));
			if (keyed.selectedSource() == LmdbNativeAccessFacts.Source.ADJACENCY) {
				continue;
			}
			if (keyed.prefixMask() <= 0 || keyed.residualFields() > 0) {
				// every intersection step re-walks the range the index cannot seek into
				penalty = penalty.plus(perRow(Feature.SCANNED_ROW, rows * keyed.scannedRows()));
			}
		}
		return penalty;
	}

	/** {@code count} occurrences of {@code feature}; an unknown count makes the vector unbounded. */
	static LmdbNativeCostVector perRow(Feature feature, double count) {
		if (Double.isNaN(count)) {
			return unbounded();
		}
		return count <= 0D ? LmdbNativeCostVector.zero() : LmdbNativeCostVector.point(feature, count);
	}

	private static double multiply(double rows, double factor) {
		return Double.isNaN(rows) ? Double.NaN : rows * factor;
	}
}
